<script lang="ts">
  import LibraryPosterGrid from '../../src/lib/LibraryPosterGrid.svelte';
  import LibraryQueueStatus from '../../src/lib/LibraryQueueStatus.svelte';
  import LibraryTvReview from '../../src/lib/LibraryTvReview.svelte';
  import { createWorkspaceState } from '../../src/lib/workspace.svelte.js';
  import { selectQueuePaths } from '../../src/lib/workspace-state.js';
  import type { LibraryPosterCard } from '../../src/lib/types.js';
  const workspace = createWorkspaceState();
  let populated = $state(false), busy = $state(false), level = $state<'series'|'season'|'episode'>('series');
  let title = $state('Synthetic series');
  let cardCount = $state(1);
  const paths = ['/synthetic/series/S01E01.mkv', '/synthetic/series/S01E02.mkv'];
  const card: LibraryPosterCard = { path: paths[0], filename: 'S01E01.mkv', relativePath: 'series/S01E01.mkv', selected: false, title: 'Synthetic series', year: '2026', proposedName: 'S01E01 Pilot.mkv', proposedNeedsReview: true, posterUrl: null, localArtworkPath: '', matchState: 'none', matchLabel: 'No poster yet', provider: '', animated: false, statusLabel: 'Ready', sourceBytes: '1 MiB', profileLine: 'Synthetic SDR', streamLine: '2 video tracks', memoryLine: 'Forecast unavailable', outputLine: 'Separate output', outputIsCustom: true, error: '', warning: '', stale: '', runLabel: '', progressLabel: '', progressPercent: null, kind: 'media', seasonNumber: 1, mediaPaths: paths, selection: 'none', animation: 'none', summary: 'Two episodes', reviewLabel: 'Review episode' };
  const cards = $derived<LibraryPosterCard[]>(populated ? Array.from({length:Math.max(1,Math.min(1000,cardCount))},(_,index)=>({ ...card, path:index ? `/synthetic/performance/${index}.mkv` : card.path, title:index ? `Synthetic series ${index}` : card.title, mediaPaths:index ? [`/synthetic/performance/${index}.mkv`] : paths, selection: workspace.queue.selectedPaths.length === 2 ? 'all' : workspace.queue.selectedPaths.length ? 'some' : 'none' })) : []);
  $effect(() => { workspace.queue.sources = populated ? [{root:'/synthetic/series', status:'ready',scanResult:null,error:null,updatedAtMs:1,changedFiles:[],missingFiles:[]}] : []; });
  function record(value: string) { workspace.notice.message = value; }
</script>
<div class="app-shell" data-theme="light"><main style="width:100%;min-width:0;padding:24px">
  <label><input type="checkbox" bind:checked={populated}/>Populated library</label><label><input type="checkbox" bind:checked={busy}/>Active job</label>
  <label>Synthetic card count<input type="number" min="1" max="1000" bind:value={cardCount}/></label>
  <button type="button" onclick={()=>{workspace.queue.selectedPaths=Array.from({length:10000},(_,index)=>`/synthetic/queue/${index}.mkv`);}}>Large queue update</button>
  <label>Review level<select aria-label="Review level" bind:value={level}><option>series</option><option>season</option><option>episode</option></select></label>
  <output aria-label="Library callback">{workspace.notice.message}</output><output aria-label="Selected paths">{workspace.queue.selectedPaths.join('|')}</output>
  <LibraryQueueStatus queue={workspace.queue} {busy} scanning={true} scanProgress={{current:1,total:2,file:'Synthetic entry'}} fileName={(path) => path.split('/').at(-1) ?? path} onActivate={(path) => record(`activate:${path}`)} onRefresh={(path) => record(`refresh:${path}`)} onRemove={(path) => record(`remove:${path}`)}/>
  <LibraryPosterGrid {cards} {busy} selectedOnPage={workspace.queue.selectedPaths.length === 2 ? 1 : 0} selectedTotal={workspace.queue.selectedPaths.length} readyCount={populated?2:0} lookupMessage="Synthetic lookup" lookupFailed={false} crumbs={[{label:'Series',onSelect:()=>record('crumb')}]} reviewCurrentLabel="Review series" onReviewCurrent={()=>record('review-series')} canRename={populated} canProcess={populated} observeArtwork={()=>{}} onToggleSelect={(values,selected)=>{workspace.queue.selectedPaths=selectQueuePaths(workspace.queue.selectedPaths,values,selected);}} onToggleAnimated={(values,animated)=>record(`animated:${values.length}:${animated}`)} onOpenReview={(path)=>record(`open:${path}`)} onOpenLocation={(path)=>record(`location:${path}`)} onReview={(path)=>record(`review:${path}`)} onRename={()=>record('rename')} onMetadata={()=>record('metadata')} onRebuild={()=>record('rebuild')} onSetOutput={(path)=>record(`output:${path}`)} onClearOutput={(path)=>record(`clear:${path}`)} onSelectPage={(selected)=>{workspace.queue.selectedPaths=selectQueuePaths(workspace.queue.selectedPaths,paths,selected);}}/>
  <LibraryTvReview {level} kicker="Synthetic review" {title} year="2026" certification="TV-PG" certificationNote="Shared certificate" certificationCustom={true} plot="Synthetic plot" plotNote="Shared description" plotCustom={true} genresText="Drama" ratingText="7" ratingNote="Shared score" ratingCustom={true} seasonNumber="1" episodeNumber="2" airdate="2026-01-01" comment="Synthetic comment" commentNote="Shared comment" commentCustom={true} posterUrl="" posters={[{path:'fixture-poster',url:''}]} selectedPosterPath="" animated={false} animatedMixed={true} onTitle={(value)=>title=value} onYear={(value)=>record(`year:${value}`)} onCertification={(value)=>record(`certificate:${value}`)} onUseSharedCertification={()=>record('shared-certificate')} onPlot={(value)=>record(`plot:${value}`)} onUseSharedPlot={()=>record('shared-plot')} onGenres={(value)=>record(`genres:${value}`)} onRating={(value)=>record(`rating:${value}`)} onUseSharedRating={()=>record('shared-rating')} onSeasonNumber={(value)=>record(`season:${value}`)} onEpisodeNumber={(value)=>record(`episode:${value}`)} onAirdate={(value)=>record(`airdate:${value}`)} onComment={(value)=>record(`comment:${value}`)} onUseSharedComment={()=>record('shared-comment')} onSelectPoster={(path)=>record(`poster:${path}`)} onChooseImage={()=>record('choose-image')} onAnimated={(value)=>record(`tv-animated:${value}`)}/>
</main></div>
